--- /dev/null
+++ b/test/settings.test.js
@@ -0,0 +1,21 @@
+const test = require('node:test');
+const assert = require('node:assert/strict');
+const { getDefaults } = require('../lib/settings');
+const { createCustomer } = require('../lib/customers');
+const { formatTotal, refundTotal } = require('../lib/money');
+
+// Regression: createCustomer used to Object.assign customer prefs into the
+// require()-cached defaults, so later totals and refunds used the customer's
+// currency. This test does its own setup and does not rely on test order.
+test('customer preferences never leak into the shared defaults', () => {
+  createCustomer({ id: 'c2', name: 'Bob', prefs: { currency: 'JPY', precision: 0 } });
+  assert.equal(getDefaults().currency, 'EUR');
+  assert.equal(getDefaults().precision, 2);
+  assert.equal(formatTotal(1230), '12.30 EUR');
+  assert.equal(refundTotal([{ cents: 500 }]), '-5.00 EUR');
+});
+
+test('mutating a returned defaults object does not affect the next caller', () => {
+  getDefaults().currency = 'CHF';
+  assert.equal(getDefaults().currency, 'EUR');
+});

